import styled from '@emotion/styled';

export const StyledKpiSummaryCards = styled.div`
  display: flex;
  flex-direction: row;
  gap: 16px;
`;

export const StyledKpiSummaryCardsItem = styled.div`
  display: flex;
  flex-direction: column;
  gap: 16px;
`;

export const StyledKpiSummaryCardsLoading = styled.div`
  display: flex;
  width: 100%;
  gap: 16px;
`;
